CREATE TABLE IF NOT EXISTS academic_cycles (id SERIAL PRIMARY KEY, name VARCHAR(30) UNIQUE NOT NULL, start_date DATE, end_date DATE, is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS programs (id SERIAL PRIMARY KEY, code VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL);
CREATE TABLE IF NOT EXISTS sections (id SERIAL PRIMARY KEY, program_id INT REFERENCES programs(id), semester INT NOT NULL, name VARCHAR(10) NOT NULL, UNIQUE(program_id,semester,name));
CREATE TABLE IF NOT EXISTS faculty (id SERIAL PRIMARY KEY, faculty_code VARCHAR(30) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL, email VARCHAR(150) UNIQUE, phone VARCHAR(30), designation VARCHAR(100), department VARCHAR(100), is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS students (id SERIAL PRIMARY KEY, usn VARCHAR(30) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL, email VARCHAR(150), phone VARCHAR(30), section_id INT REFERENCES sections(id), mentor_faculty_id INT REFERENCES faculty(id), is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, username VARCHAR(80) UNIQUE NOT NULL, password_hash TEXT NOT NULL, display_name VARCHAR(150) NOT NULL, role VARCHAR(30) NOT NULL CHECK(role IN ('ADMIN','COORDINATOR','FACULTY','SUPERVISOR','STUDENT')), faculty_id INT REFERENCES faculty(id), student_id INT REFERENCES students(id), is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS supervisor_assignments (id SERIAL PRIMARY KEY, cycle_id INT REFERENCES academic_cycles(id), section_id INT REFERENCES sections(id), faculty_id INT REFERENCES faculty(id), is_primary BOOLEAN DEFAULT FALSE, is_active BOOLEAN DEFAULT TRUE, UNIQUE(cycle_id,section_id,faculty_id));
CREATE TABLE IF NOT EXISTS student_supervisor_mappings (id SERIAL PRIMARY KEY, cycle_id INT REFERENCES academic_cycles(id), student_id INT REFERENCES students(id), supervisor_assignment_id INT REFERENCES supervisor_assignments(id), UNIQUE(cycle_id,student_id));
CREATE TABLE IF NOT EXISTS teams (id SERIAL PRIMARY KEY, team_code VARCHAR(50) UNIQUE NOT NULL, team_name VARCHAR(120) NOT NULL, cycle_id INT REFERENCES academic_cycles(id), section_id INT REFERENCES sections(id), supervisor_assignment_id INT REFERENCES supervisor_assignments(id), leader_student_id INT REFERENCES students(id), status VARCHAR(30) DEFAULT 'ACTIVE', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS team_members (id SERIAL PRIMARY KEY, team_id INT REFERENCES teams(id) ON DELETE CASCADE, student_id INT REFERENCES students(id), member_role VARCHAR(30) DEFAULT 'MEMBER', UNIQUE(team_id,student_id), UNIQUE(student_id));
CREATE TABLE IF NOT EXISTS projects (id SERIAL PRIMARY KEY, title VARCHAR(250) NOT NULL, short_description VARCHAR(500) NOT NULL, description TEXT NOT NULL, domain VARCHAR(100), technology_stack TEXT, suitable_semester VARCHAR(30), difficulty VARCHAR(30), max_teams INT DEFAULT 1 CHECK(max_teams>0), published_by INT REFERENCES faculty(id), is_guiding BOOLEAN DEFAULT TRUE, status VARCHAR(30) DEFAULT 'PUBLISHED', created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS project_applications (id SERIAL PRIMARY KEY, team_id INT REFERENCES teams(id), project_id INT REFERENCES projects(id), statement TEXT, proposed_approach TEXT, status VARCHAR(30) DEFAULT 'SUBMITTED', faculty_remarks TEXT, applied_at TIMESTAMPTZ DEFAULT NOW(), decided_at TIMESTAMPTZ, UNIQUE(team_id,project_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_application_per_team ON project_applications(team_id) WHERE status IN ('SUBMITTED','DISCUSSION','ACCEPTED');
CREATE TABLE IF NOT EXISTS application_discussions (id SERIAL PRIMARY KEY, application_id INT REFERENCES project_applications(id) ON DELETE CASCADE, sender_user_id INT REFERENCES users(id), message TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS student_project_proposals (id SERIAL PRIMARY KEY, team_id INT REFERENCES teams(id), title VARCHAR(250), problem_statement TEXT, proposed_solution TEXT, technology_stack TEXT, preferred_guide_id INT REFERENCES faculty(id), status VARCHAR(30) DEFAULT 'DRAFT', submitted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS notifications (id SERIAL PRIMARY KEY, user_id INT REFERENCES users(id), title VARCHAR(150), message TEXT, link VARCHAR(300), is_read BOOLEAN DEFAULT FALSE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS import_history (id SERIAL PRIMARY KEY, import_type VARCHAR(30), file_name VARCHAR(255), total_rows INT, success_rows INT, failed_rows INT, imported_by INT REFERENCES users(id), imported_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, user_id INT REFERENCES users(id), action VARCHAR(100), entity_name VARCHAR(100), entity_id INT, details JSONB, created_at TIMESTAMPTZ DEFAULT NOW());
